        d1 += arr[i][i];
        d2 += arr[i][4 - i];
    }
    if (d1 > maxv) maxv = d1; if (d1 < minv) minv = d1;
    if (d2 > maxv) maxv = d2; if (d2 < minv) minv = d2;

    return maxv - minv;
}

